import { createReadStream, createWriteStream, mkdtempSync, writeFileSync, readFileSync, rmSync } from 'node:fs';
import { pipeline } from 'node:stream/promises';
import { join } from 'node:path';
const directory = mkdtempSync(join(process.argv[2], 'io-'));
try {
  const input = join(directory, 'input');
  const output = join(directory, 'output');
  writeFileSync(input, Buffer.from([255, 0, 65, 13, 10]));
  await pipeline(createReadStream(input), createWriteStream(output));
  const hex = readFileSync(output).toString('hex');
  if (hex !== 'ff00410d0a') throw new Error('native binary file copy failed');
  console.log(hex);
} finally { rmSync(directory, { recursive: true, force: true }); }

